static uint8_t emv_aid_prefix_match_len(
    const uint8_t* a,
    uint8_t a_len,
    const uint8_t* b,
    uint8_t b_len) {
    uint8_t max_len = a_len < b_len ? a_len : b_len;
    uint8_t i = 0;
    while(i < max_len && a[i] == b[i]) i++;
    return i;
}

bool emv_aid_db_lookup(const uint8_t* aid, uint8_t aid_len, const char** name_out) {
    const EmvAidEntry* best = NULL;
    uint8_t best_match = 0;
    for(size_t i = 0; i < sizeof(emv_aid_table) / sizeof(emv_aid_table[0]); i++) {
        const EmvAidEntry* entry = &emv_aid_table[i];
        if(entry->aid_len == aid_len &&
           emv_aid_prefix_match_len(entry->aid, entry->aid_len, aid, aid_len) == aid_len) {
            *name_out = entry->name;
            return true;
        }
        uint8_t match = emv_aid_prefix_match_len(entry->aid, entry->aid_len, aid, aid_len);
        if(match >= 5 && match > best_match) {
            best_match = match;
            best = entry;
        }
    }
    if(best) {
        *name_out = best->name;
        return true;
    }
    return false;
}

